package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.activity.OnBackPressedCallback;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.fragment.app.FragmentActivity;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.documentscanner.*;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;import org.json.*;import java.text.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;

public class PersonalInformationActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final TextRecognizer recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);private final ArrayList<JSONObject> entries=new ArrayList<>();private PrivateHubRepository repo;private LinearLayout list;private TextView count;
 private final ActivityResultLauncher<IntentSenderRequest> scanner=registerForActivityResult(new ActivityResultContracts.StartIntentSenderForResult(),this::scanResult);
 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){@Override public void handleOnBackPressed(){goHome();}});repo=new PrivateHubRepository(this);build();load();}
 private void build(){LinearLayout page=VaultPageUi.page(this);LinearLayout bar=VaultPageUi.header(this,"Personal Information","Private details");TextView addTop=VaultPageUi.iconButton(this,"+","Add Personal Information");addTop.setOnClickListener(v->editor(null,"","","Manual Entry"));bar.addView(addTop,new LinearLayout.LayoutParams(Ui.dp(this,44),Ui.dp(this,44)));page.addView(bar);count=Ui.text(this,"Opening Encrypted Information…",11,Ui.MUTED);count.setPadding(Ui.dp(this,2),Ui.dp(this,12),0,Ui.dp(this,8));page.addView(count);TextView search=Ui.text(this,"⌕   Search saved titles",14,Ui.MUTED);search.setPadding(Ui.dp(this,14),0,Ui.dp(this,14),0);search.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,14)));page.addView(search,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));LinearLayout actions=new LinearLayout(this);TextView add=VaultPageUi.secondary(this,"Add Info"),ocr=VaultPageUi.secondary(this,"Scan With OCR");add.setOnClickListener(v->editor(null,"","","Manual Entry"));ocr.setOnClickListener(v->startOcr());LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,Ui.dp(this,46),1);ap.setMargins(0,Ui.dp(this,10),Ui.dp(this,4),0);actions.addView(add,ap);LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(0,Ui.dp(this,46),1);op.setMargins(Ui.dp(this,4),Ui.dp(this,10),0,0);actions.addView(ocr,op);page.addView(actions);page.addView(VaultPageUi.section(this,"Saved Information"));list=Ui.column(this);page.addView(list);setContentView(VaultPageUi.scroll(this,page));}
 private void load(){io.execute(()->{try{JSONArray data=repo.info();entries.clear();for(int i=data.length()-1;i>=0;i--)entries.add(data.getJSONObject(i));runOnUiThread(this::render);}catch(Exception error){runOnUiThread(()->Ui.toast(this,"Could Not Open Personal Information"));}});}
 private void render(){list.removeAllViews();count.setText(entries.size()+" Saved Item"+(entries.size()==1?"":"s"));if(entries.isEmpty()){TextView empty=Ui.text(this,"No information saved yet. Add it manually or scan a document to extract its text.",15,Ui.MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(Ui.dp(this,24),Ui.dp(this,42),Ui.dp(this,24),Ui.dp(this,42));empty.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,18)));list.addView(empty);return;}for(JSONObject item:entries)list.addView(bubble(item),bubbleParams());}
 private View bubble(JSONObject item){LinearLayout wrap=Ui.column(this);wrap.setPadding(Ui.dp(this,16),Ui.dp(this,15),Ui.dp(this,16),Ui.dp(this,15));wrap.setBackground(Ui.stroke(Ui.SOFT,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,18)));TextView title=Ui.title(this,item.optString("title","Saved Information"),16);title.setTextColor(Ui.INK);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);wrap.addView(title);wrap.setContentDescription("Open "+item.optString("title","Saved Information"));wrap.setOnClickListener(v->editor(item,item.optString("title"),item.optString("body"),item.optString("source")));wrap.setOnLongClickListener(v->{options(item);return true;});return wrap;}
 private LinearLayout.LayoutParams bubbleParams(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.leftMargin=Ui.dp(this,34);p.bottomMargin=Ui.dp(this,10);return p;}
 private void editor(JSONObject item,String heading,String text,String source){LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,6),Ui.dp(this,18),0);EditText title=Ui.field(this,"Information title",false);title.setText(heading);box.addView(title,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));EditText body=new EditText(this);body.setHint("Information or notes");body.setText(text);body.setTextSize(16);body.setTextColor(Ui.INK);body.setHintTextColor(Ui.MUTED);body.setGravity(Gravity.TOP);body.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,12));body.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,14)));body.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,Ui.dp(this,190));bp.topMargin=Ui.dp(this,10);box.addView(body,bp);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(item==null?"Add Personal Information":"Edit Personal Information").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String name=title.getText().toString().trim(),value=body.getText().toString().trim();if(name.isEmpty()){title.setError("Add a title");return;}if(value.isEmpty()){body.setError("Add information to save");return;}dialog.getButton(-1).setEnabled(false);io.execute(()->{try{if(item==null)repo.addInfo(name,value,source);else repo.updateInfo(item.optString("id"),name,value);runOnUiThread(()->{dialog.dismiss();load();});}catch(Exception error){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);Ui.toast(this,"Could Not Save This Information");});}});}));dialog.getWindow();dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void options(JSONObject item){String[] options={"Edit","Copy Text","Delete"};new AlertDialog.Builder(this).setTitle(item.optString("title")).setItems(options,(d,which)->{if(which==0)editor(item,item.optString("title"),item.optString("body"),item.optString("source"));else if(which==1){ClipboardManager clipboard=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText(item.optString("title"),item.optString("body")));Ui.toast(this,"Information Copied");}else new AlertDialog.Builder(this).setTitle("Delete This Information?").setMessage("This permanently removes the encrypted entry.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,w)->io.execute(()->{try{repo.deleteInfo(item.optString("id"));runOnUiThread(this::load);}catch(Exception error){runOnUiThread(()->Ui.toast(this,"Could Not Delete This Information"));}})).show();}).show();}
 private void startOcr(){GmsDocumentScannerOptions options=new GmsDocumentScannerOptions.Builder().setGalleryImportAllowed(true).setPageLimit(10).setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG).setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL).build();GmsDocumentScanning.getClient(options).getStartScanIntent(this).addOnSuccessListener(sender->scanner.launch(new IntentSenderRequest.Builder(sender).build())).addOnFailureListener(error->Ui.toast(this,"Text Scanner Unavailable"));}
 private void scanResult(ActivityResult result){if(result.getResultCode()!=RESULT_OK)return;GmsDocumentScanningResult scan=GmsDocumentScanningResult.fromActivityResultIntent(result.getData());if(scan==null||scan.getPages()==null||scan.getPages().isEmpty()){Ui.toast(this,"No Page Was Scanned");return;}ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Reading Text Securely…");wait.show();StringBuilder output=new StringBuilder();AtomicInteger remaining=new AtomicInteger(scan.getPages().size());for(GmsDocumentScanningResult.Page page:scan.getPages()){try{InputImage image=InputImage.fromFilePath(this,page.getImageUri());recognizer.process(image).addOnSuccessListener(text->{synchronized(output){if(output.length()>0)output.append("\n\n");output.append(text.getText().trim());}finishOcr(remaining,output,wait);}).addOnFailureListener(error->finishOcr(remaining,output,wait));}catch(Exception error){finishOcr(remaining,output,wait);}}}
 private void finishOcr(AtomicInteger remaining,StringBuilder output,ProgressDialog wait){if(remaining.decrementAndGet()!=0)return;wait.dismiss();String text=output.toString().trim();if(text.isEmpty()){Ui.toast(this,"No Readable Text Was Found");return;}editor(null,"Scanned Information",text,"OCR");}
 private void goHome(){startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
 @Override protected void onResume(){super.onResume();if(!Session.valid())finish();}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onDestroy(){super.onDestroy();recognizer.close();io.shutdownNow();}
}
